  private string UpdateMessage(){try{var status=Json.Text(Json.Read(File.ReadAllText(Path.Combine(profile,"updates.json"))),"status");switch(status){case "update_checking":return "새 버전을 확인하고 있어요.";case "update_unavailable":return "현재 최신 버전입니다.";case "update_available":return "새 버전이 있어요. 준비되면 다시 확인해 주세요.";case "update_downloading":case "applying":return "검증 후 업데이트를 설치합니다.";case "installed":return "최신 버전으로 업데이트했습니다.";case "update_rate_limit":return "GitHub 요청 한도로 잠시 후 다시 확인합니다.";case "recovery_required":return "복구가 필요합니다. 설치 안내에서 새 패키지를 받아 주세요.";default:return "확인에 실패했어요. 기존 앱은 계속 사용할 수 있습니다.";}}catch{return "현재 "+ReleaseVersion()+" · 자동 설치는 기본으로 꺼져 있어요.";}}
  private void CheckUpdates(bool force){
   if(Environment.GetEnvironmentVariable("WORKLOG_DISABLE_UPDATE_CHECK")=="1"||!string.IsNullOrEmpty(Environment.GetEnvironmentVariable("WORKLOG_QA_EMAIL"))||client.ApiBase.StartsWith("http:")||!File.Exists(Path.Combine(root,"release.json")))return;
   try{if(updateProcess!=null&&!updateProcess.HasExited)return;var info=new System.Diagnostics.ProcessStartInfo{FileName=Path.Combine(Environment.SystemDirectory,"WindowsPowerShell\\v1.0\\powershell.exe"),Arguments="-NoProfile -NonInteractive -STA -ExecutionPolicy Bypass -File \""+Path.Combine(root,"desktop/windows/Update.ps1")+"\" -TargetRoot \""+root+"\" -Profile \""+profile+"\""+(force?" -Force":""),WorkingDirectory=Path.GetTempPath(),UseShellExecute=false,CreateNoWindow=true};info.EnvironmentVariables["WORKLOG_SCRIPTS_HOME"]=profile;updateProcess=System.Diagnostics.Process.Start(info);}
   catch{message="업데이트를 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.";Render();}
  }
  private void OpenLink(string url){try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(url){UseShellExecute=true});}catch{message="브라우저를 열지 못했습니다.";Render();}}
  private CheckBox Switch(StackPanel parent,string title,bool value){var c=new CheckBox{Content=title,IsChecked=value,Margin=new Thickness(0,3,0,3)};parent.Children.Add(c);return c;}
  private Slider Range(StackPanel parent,string title,double value){var row=new DockPanel{Margin=new Thickness(0,4,0,4)};var number=Copy(Math.Round(value*100)+"%",12,"Accent",true);DockPanel.SetDock(number,Dock.Right);row.Children.Add(number);row.Children.Add(Copy(title,12,"Muted"));parent.Children.Add(row);var slider=new Slider{Minimum=.1,Maximum=1,Value=value,TickFrequency=.05,IsSnapToTickEnabled=true,Margin=new Thickness(0,2,0,12)};slider.ValueChanged+=(s,e)=>number.Text=Math.Round(slider.Value*100)+"%";parent.Children.Add(slider);return slider;}
  private TextBox ColorInput(StackPanel parent,string title,string value){parent.Children.Add(Copy(title,12,"Muted"));var row=new DockPanel{Margin=new Thickness(0,5,0,12)};var swatch=Command("",()=>{});swatch.Width=42;swatch.Margin=new Thickness(10,0,0,0);swatch.Background=new SolidColorBrush(Parse(value));DockPanel.SetDock(swatch,Dock.Right);row.Children.Add(swatch);var input=new TextBox{Text=value};row.Children.Add(input);parent.Children.Add(row);input.TextChanged+=(s,e)=>{try{swatch.Background=new SolidColorBrush(Parse(input.Text));}catch{}};swatch.Click+=(s,e)=>{using(var picker=new Forms.ColorDialog()){var c=Parse(ValidColor(input.Text,value));picker.Color=System.Drawing.Color.FromArgb(c.R,c.G,c.B);if(picker.ShowDialog()==Forms.DialogResult.OK){input.Text=string.Format("#{0:X2}{1:X2}{2:X2}",picker.Color.R,picker.Color.G,picker.Color.B);}}};return input;}
 }
